with card_content(display_order, question_text, question_translation, answer_examples) as (
  values
    (21, 'What do you usually do in the morning?', 'O que você costuma fazer de manhã?', '[{"answer":"I have breakfast and get ready for work.","translation":"Eu tomo café da manhã e me preparo para o trabalho.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I take a shower and make coffee.","translation":"Eu tomo banho e faço café.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I usually exercise before work.","translation":"Eu geralmente faço exercícios antes do trabalho.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I check my schedule and start working.","translation":"Eu verifico minha agenda e começo a trabalhar.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I have a quiet breakfast and read the news.","translation":"Eu tomo um café da manhã tranquilo e leio as notícias.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (22, 'What do you usually have for breakfast?', 'O que você costuma comer no café da manhã?', '[{"answer":"I usually have coffee and bread.","translation":"Eu geralmente tomo café e como pão.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I have fruit and yogurt.","translation":"Eu como frutas e iogurte.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I normally eat eggs and toast.","translation":"Eu normalmente como ovos e torradas.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I just have coffee in the morning.","translation":"Eu só tomo café de manhã.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I like having cheese bread and coffee.","translation":"Eu gosto de comer pão de queijo e tomar café.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (23, 'What time do you start work or school?', 'Que horas você começa a trabalhar ou estudar?', '[{"answer":"I start work at nine.","translation":"Eu começo a trabalhar às nove.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"My workday starts at eight thirty.","translation":"Meu expediente começa às oito e meia.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I usually start at ten.","translation":"Eu geralmente começo às dez.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Classes start at seven in the morning.","translation":"As aulas começam às sete da manhã.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"My schedule changes, but I normally start around nine.","translation":"Meu horário muda, mas normalmente começo por volta das nove.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (24, 'What do you usually do during the day?', 'O que você costuma fazer durante o dia?', '[{"answer":"I work and attend meetings.","translation":"Eu trabalho e participo de reuniões.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I study in the morning and work in the afternoon.","translation":"Eu estudo de manhã e trabalho à tarde.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I spend most of the day at work.","translation":"Eu passo a maior parte do dia no trabalho.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I work, answer emails, and talk to clients.","translation":"Eu trabalho, respondo e-mails e falo com clientes.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"My day is usually divided between work, errands, and family.","translation":"Meu dia geralmente se divide entre trabalho, tarefas e família.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (25, 'What time do you usually go to bed?', 'Que horas você costuma ir para a cama?', '[{"answer":"I usually go to bed at eleven.","translation":"Eu geralmente vou para a cama às onze.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I go to bed around midnight.","translation":"Eu vou para a cama por volta da meia-noite.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I normally sleep at ten thirty.","translation":"Eu normalmente durmo às dez e meia.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"On weekdays, I try to be in bed by eleven.","translation":"Nos dias de semana, eu tento estar na cama até as onze.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"It depends on the day, but usually before midnight.","translation":"Depende do dia, mas geralmente antes da meia-noite.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (26, 'Are you a morning person or a night person?', 'Você é uma pessoa mais matutina ou noturna?', '[{"answer":"I''m definitely a morning person.","translation":"Eu definitivamente sou uma pessoa matutina.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''m more of a night person.","translation":"Eu sou mais uma pessoa noturna.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I prefer mornings because I have more energy.","translation":"Eu prefiro as manhãs porque tenho mais energia.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I work better at night.","translation":"Eu trabalho melhor à noite.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''m somewhere in between.","translation":"Eu fico em algum lugar no meio.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (27, 'What do you like to do in your free time?', 'O que você gosta de fazer no seu tempo livre?', '[{"answer":"I like reading and watching movies.","translation":"Eu gosto de ler e assistir a filmes.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I enjoy spending time with friends.","translation":"Eu gosto de passar tempo com amigos.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I like going for walks.","translation":"Eu gosto de fazer caminhadas.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I usually listen to music or play games.","translation":"Eu geralmente ouço música ou jogo.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I like relaxing at home and trying new recipes.","translation":"Eu gosto de relaxar em casa e experimentar receitas novas.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (28, 'What are your hobbies?', 'Quais são os seus hobbies?', '[{"answer":"My hobbies are reading and cooking.","translation":"Meus hobbies são ler e cozinhar.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I enjoy photography.","translation":"Eu gosto de fotografia.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I like playing soccer and watching movies.","translation":"Eu gosto de jogar futebol e assistir a filmes.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I enjoy traveling and learning languages.","translation":"Eu gosto de viajar e aprender idiomas.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I spend a lot of my free time gardening and listening to music.","translation":"Eu passo muito do meu tempo livre cuidando do jardim e ouvindo música.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (29, 'Do you like reading?', 'Você gosta de ler?', '[{"answer":"Yes, I love reading.","translation":"Sim, eu adoro ler.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Yes, especially fiction.","translation":"Sim, especialmente ficção.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I read from time to time.","translation":"Eu leio de vez em quando.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Not very much, to be honest.","translation":"Não muito, para ser sincero/a.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I like reading when I have enough time.","translation":"Eu gosto de ler quando tenho tempo suficiente.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (30, 'What kind of books do you like?', 'Que tipo de livros você gosta?', '[{"answer":"I like mystery novels.","translation":"Eu gosto de romances de mistério.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I enjoy science fiction.","translation":"Eu gosto de ficção científica.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I usually read biographies.","translation":"Eu geralmente leio biografias.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I prefer non-fiction books.","translation":"Eu prefiro livros de não ficção.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I like books about history and psychology.","translation":"Eu gosto de livros sobre história e psicologia.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb)
)
update public.conversation_questions as question
set question_text=content.question_text, question_translation=content.question_translation, answer_examples=content.answer_examples
from card_content as content where question.display_order=content.display_order;
